B.agk=s([B.bc1],t.e)
B.bqk=new A.hf("N\u011bkdy se mus\xed\u0161 o kousek vr\xe1tit, a\u0165 se dostane\u0161 d\xe1l.","P\u0159elij ze zvednut\xe9 n\xe1doby do t\xe9, kter\xe1 sv\xedt\xed. Cesta dop\u0159edu n\u011bkdy vede kousek zp\xe1tky.")
B.agl=s([B.bqk],t.AE)
B.a4h=new A.j(0.7019607843137254,1,0.8784313725490196,0.5490196078431373,B.d)
