B.agm=s([B.a4h,B.a4e,B.a00],t.W)
B.axY=new A.aQ("Je \u010dtvrtek odpoledne a t\u0159\xedda je na v\xfdlet\u011b v muzeu. Vstupn\xed hala je pln\xe1 d\u011bt\xed. Dupou po schodech, \u0161eptaj\xed si a sm\u011bj\xed se. Ema, Jon\xe1\u0161, Nela a ty se zastav\xedte u velk\xe9ho obrazu u hlavn\xedch dve\u0159\xed. Je na n\u011bm vzne\u0161en\xe1 d\xe1ma v \u0161atech, kter\xe1 sp\xed. A tv\xe1\u0159\xed se p\u011bkn\u011b nerudn\u011b.")
B.aQ=new A.kq("ema","assets/images/stories/museum/story/portrait_ema.webp")
B.aid=s(["\u201e\u201aBaronka Frida von\u2026 Schla\u2026 Scho\u2026 Schovanburger.\u2018 Schovan\xfd burger? Kter\xfd bl\xe1zen by schov\xe1val burger?\u201c"],t.s)
B.bkP=new A.a6(B.aQ,B.aid,!1)
B.aY=new A.kq("jonas","assets/images/stories/museum/story/portrait_jonas.webp")
B.ahr=s(["\u201eSchlafenberg, Emo. \u017d\xe1dn\xfd schovan\xfd burger. Schlafen je n\u011bmecky sp\xe1t a Berg je hora. Kdy\u017e si to p\u0159elo\u017e\xed\u0161, tak je to Baronka ze Spac\xed hory.\u201c"],t.s)
B.bld=new A.a6(B.aY,B.ahr,!1)
B.b3=new A.kq("nela","assets/images/stories/museum/story/portrait_nela.webp")
B.aoB=s(["\u201eTak to se na t\xe9 ho\u0159e asi moc dob\u0159e nesp\xed. Vypad\xe1, \u017ee nespala celou v\u011b\u010dnost.\u201c"],t.s)
B.blO=new A.a6(B.b3,B.aoB,!1)
B.ayl=new A.aQ("Pod jm\xe9nem baronky vis\xed je\u0161t\u011b jedna men\u0161\xed cedulka.")
B.aeR=s(["\u201e\u201aZ\xedtra r\xe1no se obraz st\u011bhuje do nov\xe9 galerie na hlavn\xedm n\xe1dra\u017e\xed.\u2018\u201c"],t.s)
B.bne=new A.a6(B.aQ,B.aeR,!1)
B.aym=new A.aQ("Jon\xe1\u0161 by p\u0159\xedsahal, \u017ee se baronka v tu chv\xedli zamra\u010dila je\u0161t\u011b v\xedc.")
B.aph=s([B.axY,B.bkP,B.bld,B.blO,B.ayl,B.bne,B.aym],t.a)
B.boT=new A.cq("story_01",B.aph)
B.axy=new A.aQ("Kdy\u017e exkurze skon\u010d\xed, v\u0161ichni sp\u011bchaj\xed k autobusu. Teda t\xe9m\u011b\u0159 v\u0161ichni.")
B.aiM=s(["\u201ePsst. M\xe1m pl\xe1n. Schov\xe1me se v \u0161atn\u011b a muzeum bude v noci jen na\u0161e.\u201c"],t.s)
B.bkw=new A.a6(B.aQ,B.aiM,!1)
B.agV=s(["\u201eTo je ten nejhor\u0161\xed pl\xe1n, jak\xfd jsem kdy sly\u0161el.\u201c"],t.s)
B.bkv=new A.a6(B.aY,B.agV,!1)
B.axk=new A.aQ("Autobus odjede. Muzeum se zav\u0159e a sv\u011btla zhasnou. V\u0161echny hodiny v muzeu se v tu chv\xedli zastav\xed a ru\u010di\u010dky sko\u010d\xed na p\u016flnoc.")
B.aoH=s(["\u201eZavol\xe1m dom\u016f, \u017ee se exkurze trochu prot\xe1hne. Hm. Nem\xe1m sign\xe1l, ani \u010d\xe1rku.\u201c"],t.s)
B.bm8=new A.a6(B.b3,B.aoH,!1)
B.ahn=s(["\u201eA vstupn\xed dve\u0159e jsou zam\u010den\xe9! Jako by n\xe1s muzeum necht\u011blo pustit ven.\u201c"],t.s)
B.bko=new A.a6(B.aY,B.ahn,!1)
B.axq=new A.aQ("A d\u011bti poprv\xe9 napadne, \u017ee se odsud mo\u017en\xe1 nedostanou. Ani dnes. Ani nikdy.")
B.acf=s(["\u201eTak nebudeme \u010dekat. Prozkoum\xe1me to tu. Jenom pot\u0159ebujeme sv\u011btlo.\u201c"],t.s)
B.bnE=new A.a6(B.aQ,B.acf,!1)
B.axw=new A.aQ("V muzeu je prapodivn\xe9 ticho. V \u0161atn\u011b na zdi nejist\u011b blik\xe1 lampa. Nela najde u dve\u0159\xed star\xfd oto\u010dn\xfd vyp\xedna\u010d a zku\u0161en\u011b s n\xedm p\xe1rkr\xe1t cvakne. Lampa zaprask\xe1, zablik\xe1 a rozsv\xedt\xed se naplno.")
B.agC=s([B.axy,B.bkw,B.bkv,B.axk,B.bm8,B.bko,B.axq,B.bnE,B.axw],t.a)
B.boM=new A.cq("story_02",B.agC)
B.ay_=new A.aQ("Posledn\xed sk\u0159\xed\u0148ka se s vrznut\xedm otev\u0159e a na zem vypadne sto\u010den\xfd svitek. Je to pl\xe1nek muzea, nakreslen\xfd rukou. Na druh\xe9 stran\u011b je n\u011bco naps\xe1no rozt\u0159esen\xfdm p\xedsmem.")
B.ag2=s(["\u201e\u201aKdo chce ven, mus\xed z\xedskat p\u016flno\u010dn\xed kl\xed\u010d. Nev\u011b\u0159te jej\xedmu \xfasm\u011bvu. V. T.\u2018\u201c"],t.s)
B.bnc=new A.a6(B.aY,B.ag2,!1)
B.alU=s(["\u201eKdo je V. T.? A jak\xe9mu \xfasm\u011bvu?\u201c"],t.s)
B.blg=new A.a6(B.aQ,B.alU,!1)
B.anP=s(["\u201eSuper. Jsme zam\u010den\xed v muzeu a dost\xe1v\xe1me podivn\xe9 vzkazy. U\u017e tu chyb\xed jen stra\u0161idlo.\u201c"],t.s)
B.bn7=new A.a6(B.b3,B.anP,!1)
B.axm=new A.aQ("Z chodby se ozve tich\xe9 \u0161ust\u011bn\xed dlouh\xfdch sukn\xed. A pak ospal\xfd \u0161epot, tak tich\xfd, \u017ee to mohl b\xfdt i pr\u016fvan:")
B.xS=new A.kq("baroness","assets/images/stories/museum/story/portrait_baroness.webp")
B.apS=s(["\u201eRuhe\u2026\u201c"],t.s)
B.bl2=new A.a6(B.xS,B.apS,!0)
B.ahm=s(["\u201eTo je n\u011bmecky. Znamen\xe1 to\u2026 ticho.\u201c"],t.s)
B.bnV=new A.a6(B.aY,B.ahm,!1)
B.ayb=new A.aQ("V\u0161em se zatajuje dech, proto\u017ee ta chodba je pr\xe1zdn\xe1.")
B.ayc=new A.aQ("D\u011bti rychle rozlo\u017e\xed pl\xe1nek na podlaze. Jen\u017ee tma na pap\xed\u0159e se pohne. P\u0159es chodby a s\xe1ly se pomalu val\xed \u010dern\xe1 mlha a schov\xe1v\xe1 cestu. Vid\u011bt je jen \u0161atna, kde pr\xe1v\u011b stoj\xed.")
B.aqZ=s(["\u201eK \u010demu n\xe1m je zaml\u017een\xfd pl\xe1nek? Co s t\xedm chcete d\u011blat? Hr\xe1t na schov\xe1vanou?\u201c"],t.s)
B.bn_=new A.a6(B.b3,B.aqZ,!1)
B.akV=s(["\u201eTen pl\xe1nek n\xe1s n\u011bkam vede. Tak jdeme zjistit kam.\u201c"],t.s)
B.blr=new A.a6(B.aQ,B.akV,!1)
B.am6=s(["\u201eEmo, po\u010dkej\u2026 Emo!\u201c"],t.s)
B.bmb=new A.a6(B.aY,B.am6,!1)
B.apN=s([B.ay_,B.bnc,B.blg,B.bn7,B.axm,B.bl2,B.bnV,B.ayb,B.ayc,B.bn_,B.blr,B.bmb],t.a)
B.bp_=new A.cq("story_03",B.apN)
B.ayO=new A.aQ("Posledn\xed dve\u0159e se otev\u0159ou a na pl\xe1nku se rozz\xe1\u0159\xed nakreslen\xe1 kost. D\u011bti stoj\xed p\u0159esn\u011b tam, kam je pl\xe1nek vedl, v s\xe1le dinosaur\u016f. Sv\xedt\xed tady jen jedna lampa. Uprost\u0159ed se ve tm\u011b r\xfdsuje n\u011bco obrovsk\xe9ho.")
B.ar8=s(["\u201eEmo\u2026 to obrovsk\xe9 cosi\u2026 se pr\xe1v\u011b pohnulo?\u201c"],t.s)
B.bn4=new A.a6(B.aY,B.ar8,!1)
B.ayA=new A.aQ("Ze tmy se ozve tich\xe9, dlouh\xe9, kostnat\xe9 zask\u0159\xedp\xe1n\xed.")
B.af_=s(["\u201e\u0158ekn\u011bte mi, \u017ee to byly dve\u0159e.\u201c"],t.s)
B.bky=new A.a6(B.b3,B.af_,!1)
B.ah1=s([B.ayO,B.bn4,B.ayA,B.bky],t.a)
B.bp0=new A.cq("story_04",B.ah1)
B.axv=new A.aQ("Posledn\xed kost zapadne na sv\xe9 m\xedsto. Kostra se zachv\u011bje, pomalu zvedne hlavu\u2026 a uk\xe1\u017ee \u010delist\xed k p\xedskovi\u0161ti v rohu s\xe1lu.")
B.al8=s(["\u201eEhm. D\u011bkujeme?\u201c"],t.s)
B.bnS=new A.a6(B.aQ,B.al8,!1)
B.adq=s(["\u201eRozum\xedm tomu spr\xe1vn\u011b, \u017ee n\xe1m pr\xe1v\u011b poradil dinosaurus?\u201c"],t.s)
B.bkU=new A.a6(B.b3,B.adq,!1)
B.ayj=new A.aQ("P\xedskovi\u0161t\u011b ale vypad\xe1 \xfapln\u011b oby\u010dejn\u011b. Hromada p\xedsku a v n\xed\u2026 nic.")
B.aro=s(["\u201e\u017d\xe1dn\xe1 cedulka. \u017d\xe1dn\xfd vzkaz. \u017d\xe1dn\xe1 \u0161ipka \u201aKl\xed\u010d je tady\u2018. To je teda pomoc.\u201c"],t.s)
B.blt=new A.a6(B.b3,B.aro,!1)
B.ahu=s([B.axv,B.bnS,B.bkU,B.ayj,B.blt],t.a)
B.bpj=new A.cq("story_05",B.ahu)
B.ax8=new A.aQ("P\xedskovi\u0161t\u011b se ot\u0159ese, zadun\xed a p\xedsek vyst\u0159el\xed a\u017e ke stropu. Kdy\u017e se prach usad\xed, le\u017e\xed uprost\u0159ed kr\xe1teru zlat\xfd \xfalomek kl\xed\u010de. Je na n\u011bm vyryt\xe1 kost. Jon\xe1\u0161 vyt\xe1hne vzkaz.")
B.aqz=s(["\u201e\u201aKdo chce ven, mus\xed z\xedskat p\u016flno\u010dn\xed kl\xed\u010d.\u2018 Jen\u017ee tohle nen\xed cel\xfd kl\xed\u010d. Je to jen kus!\u201c"],t.s)
B.bmQ=new A.a6(B.aY,B.aqz,!1)
B.ahU=s(["\u201eTak\u017ee zbytek bude schovan\xfd n\u011bkde jinde v muzeu.\u201c"],t.s)
B.bkp=new A.a6(B.b3,B.ahU,!1)
B.ax_=new A.aQ("Lampa zablik\xe1 a zhasne. Ve tm\u011b se ozve dlouh\xe9, ospal\xe9 z\xedvnut\xed. Kdy\u017e se lampa znovu rozsv\xedt\xed, v s\xe1le nikdo nen\xed.")
B.amS=s(["\u201eKdo z v\xe1s to byl?\u201c"],t.s)
B.bkk=new A.a6(B.aQ,B.amS,!1)
B.apC=s(["\u201eJ\xe1 ne!\u201c"],t.s)
B.bm1=new A.a6(B.aY,B.apC,!1)
B.anO=s([B.ax8,B.bmQ,B.bkp,B.ax_,B.bkk,B.bm1],t.a)
B.bpe=new A.cq("story_06",B.anO)
B.ay3=new A.aQ("D\u011bti doraz\xed do dal\u0161\xedho s\xe1lu. Je chladn\xfd a tajemn\u011b tich\xfd. Jde o egyptsk\xfd s\xe1l, je pln\xfd sarkof\xe1g\u016f, mumi\xed a soch d\xe1vn\xfdch boh\u016f. Mal\xfdm oknem pod stropem dopad\xe1 m\u011bs\xed\u010dn\xed sv\u011btlo.")
B.ajy=s(["\u201eTady n\u011bkde mo\u017en\xe1 bude dal\u0161\xed kus. Jen\u017ee kde?\u201c"],t.s)
B.bkC=new A.a6(B.aY,B.ajy,!1)
B.ayn=new A.aQ("V rohu s\xe1lu le\u017e\xed v podlaze t\u011b\u017ek\xe1 kamenn\xe1 deska. Nehne se ani o milimetr. Ema se do n\xed op\u0159e celou vahou.")
B.alZ=s(["\u201eJ\xe1 jsem v\u011bd\u011bla, \u017ee jsem m\u011bla r\xe1no sn\xedst ty dva rohl\xedky nav\xedc. \u201c"],t.s)
B.blG=new A.a6(B.aQ,B.alZ,!1)
B.asb=s([B.ay3,B.bkC,B.ayn,B.blG],t.a)
B.boW=new A.cq("story_07",B.asb)
B.ayk=new A.aQ("M\u011bs\xed\u010dn\xed paprsek dopadne na vytesan\xfd symbol oka a ten se rozz\xe1\u0159\xed zlat\xfdm sv\u011btlem. K\xe1men zahu\u010d\xed, deska v rohu odjede stranou a odkryje schody. Vedou hluboko pod zem.")
B.ae2=s(["\u201eSchody do nezn\xe1ma. No jasn\u011b. Schody do cukr\xe1rny to asi nebudou, co?\u201c"],t.s)
B.bmX=new A.a6(B.b3,B.ae2,!1)
B.axU=new A.aQ("Jon\xe1\u0161 se zastav\xed na prvn\xedm schodu. Nohy ho necht\u011bj\xed poslechnout. Nela mu str\u010d\xed do ruky baterku.")
B.afD=s(["\u201eSpr\xe1vn\xfd gentleman jde p\u0159ece prvn\xed, ne?\u201c"],t.s)
B.bn9=new A.a6(B.b3,B.afD,!1)
B.aye=new A.aQ("Jon\xe1\u0161 se zhluboka nadechne.")
B.ael=s(["\u201eD-dob\u0159e. Jdu prvn\xed. Rychle, ne\u017e si to rozmysl\xedm.\u201c"],t.s)
B.bmy=new A.a6(B.aY,B.ael,!1)
B.acr=s([B.ayk,B.bmX,B.axU,B.bn9,B.aye,B.bmy],t.a)
B.boX=new A.cq("story_08",B.acr)
B.axP=new A.aQ("Dole je hrobka. Je tu dusno, tma a ticho. Najednou to v\u0161ude zachrast\xed. Ze tmy vyb\u011bhnou drobn\xed brouci a rozprchnou se po cel\xe9 hrobce.")
B.anJ=s(["\u201eFuj! Brouci! \u017div\xed brouci!\u201c"],t.s)
B.bmn=new A.a6(B.aY,B.anJ,!1)
B.aeI=s(["\u201eKlid, Jon\xe1\u0161i. Jsou to jen brouci.\u201c"],t.s)
B.bnx=new A.a6(B.aQ,B.aeI,!1)
B.afk=s(["\u201eTo jsou skarabeov\xe9. Posv\xe1tn\xed brouci Egyp\u0165an\u016f. Ale je mi jedno, jak moc jsou posv\xe1tn\xed. Hlavn\u011b a\u0165 mi nelezou do bot.\u201c"],t.s)
B.bml=new A.a6(B.aY,B.afk,!1)
B.anS=s(["\u201eJon\xe1\u0161i, te\u010f se neh\xfdbej. Jeden ti sed\xed na hlav\u011b.\u201c"],t.s)
B.bnP=new A.a6(B.b3,B.anS,!1)
B.ahB=s(["\u201eCo\u017ee?! Sundejte ho! Sundejte ho ze m\u011b!\u201c"],t.s)
B.bmO=new A.a6(B.aY,B.ahB,!1)
B.af6=s(["\u201eD\u011bl\xe1m si legraci.\u201c"],t.s)
B.blc=new A.a6(B.b3,B.af6,!1)
B.ajB=s([B.axP,B.bmn,B.bnx,B.bml,B.bnP,B.bmO,B.blc],t.a)
B.boL=new A.cq("story_09",B.ajB)
B.ax4=new A.aQ("V\xedr v m\xedse se zpomal\xed, zastav\xed a zmiz\xed. T\u011b\u017ek\xe9 v\xedko se se sk\u0159\xedp\u011bn\xedm odsune stranou. Pod n\xedm vedou schody je\u0161t\u011b o n\u011bco hloub\u011bji.")
B.ag4=s(["\u201eMuzeum m\xe1 v\xedc pater pod zem\xed ne\u017e nad n\xed. To n\xe1m nikdo na prohl\xeddce ne\u0159ekl. Asi pod\xe1m st\xed\u017enost.\u201c"],t.s)
B.bm3=new A.a6(B.b3,B.ag4,!1)
B.ayE=new A.aQ("D\u011bti slezou dol\u016f a ocitnou se v mal\xe9m s\xe1le. \u017d\xe1dn\xe9 dve\u0159e. Nic. Jen k\xe1men a ticho.")
B.aih=s(["\u201eNic tu nen\xed. Poj\u010fme rad\u0161i zp\xe1tky nahoru, dokud je\u0161t\u011b m\u016f\u017eeme.\u201c"],t.s)
B.bms=new A.a6(B.aY,B.aih,!1)
B.aqU=s(["\u201eNikam nejdeme. Tady n\u011bco mus\xed b\xfdt.\u201c"],t.s)
B.bmz=new A.a6(B.aQ,B.aqU,!1)
B.aj5=s(["\u201eV pohod\u011b. Jsme jen hluboko pod zem\xed, v s\xe1le bez dve\u0159\xed, uprost\u0159ed noci, v muzeu, kter\xe9 n\xe1s nechce pustit. Co by se asi tak mohlo st\xe1t?\u201c"],t.s)
B.bkX=new A.a6(B.b3,B.aj5,!1)
B.abU=s([B.ax4,B.bm3,B.ayE,B.bms,B.bmz,B.bkX],t.a)
B.bpc=new A.cq("story_10",B.abU)
B.ayh=new A.aQ("Pod prvn\xedm podstavcem se otev\u0159ou padac\xed dv\xed\u0159ka. Podstavec propadne do tmy a z jeho m\xedsta pomalu vystoup\xed zlat\xfd \xfalomek kl\xed\u010de. Je na n\u011bm oko.")
B.arM=s(["\u201eDal\u0161\xed kus!\u201c"],t.s)
B.bm2=new A.a6(B.aY,B.arM,!1)
B.afw=s(["\u201eVid\xedte? Pohoda. Tohle d\xe1me levou zadn\xed.\u201c"],t.s)
B.bl5=new A.a6(B.aQ,B.afw,!1)
B.ax5=new A.aQ("D\u011bti vy\u0161plhaj\xed zp\xe1tky nahoru. Potom se odn\u011bkud z d\xe1lky ozve kovov\xe9 \u0159in\u010den\xed a slab\xfd, chraplav\xfd hlas:")
B.aF=new A.kq("clockmaker","assets/images/stories/museum/story/portrait_clockmaker.webp")
B.ae9=s(["\u201eHal\xf3\xf3\xf3? Je tam n\u011bkdo? Pros\xedm v\xe1s\u2026 kolik je hodin?\u201c"],t.s)
B.bnO=new A.a6(B.aF,B.ae9,!0)
B.ayB=new A.aQ("Hlas jde z ryt\xed\u0159sk\xe9ho s\xe1lu. Vstupn\xed chodbu ale zav\xedr\xe1 t\u011b\u017ek\xe1 \u017eelezn\xe1 m\u0159\xed\u017e. Za m\u0159\xed\u017e\xed je tma a v t\xe9 tm\u011b n\u011bkdo je.")
B.amP=s(["\u201eKone\u010dn\u011b! Lid\xe9! Ne\u0159\xedkejte mi, \u017ee se mi jenom zd\xe1te.\u201c"],t.s)
B.bnn=new A.a6(B.aF,B.amP,!0)
B.apE=s(["\u201eKdo jste?\u201c"],t.s)
B.bn2=new A.a6(B.aQ,B.apE,!1)
B.aew=s(["\u201eTo je velmi dobr\xe1 ot\xe1zka. A\u017e na to p\u0159ijdu, \u0159eknu v\xe1m to.\u201c"],t.s)
B.bnQ=new A.a6(B.aF,B.aew,!0)
B.ay9=new A.aQ("D\u011bti se chyt\xed m\u0159\xed\u017ee a zat\xe1hnou ze v\u0161ech sil. Tla\u010d\xed, lomcuj\xed s n\xed, ale m\u0159\xed\u017e se nehne ani o kousek.")
B.aqh=s([B.ayh,B.bm2,B.bl5,B.ax5,B.bnO,B.ayB,B.bnn,B.bn2,B.bnQ,B.ay9],t.a)
B.boH=new A.cq("story_11",B.aqh)
B.ay7=new A.aQ("M\u0159\xed\u017e s rachotem vyjede vzh\u016fru a v chodb\u011b se rozsv\xedt\xed. Na zemi tam sed\xed star\xfd mu\u017e v pracovn\xed z\xe1st\u011b\u0159e. Na nose m\xe1 br\xfdle, na \u010dele hodin\xe1\u0159skou lupu a ve vlasech pavu\u010dinu.")
B.ahz=s(["\u201eD\u011bkuji. Mnohokr\xe1t d\u011bkuji. Kolik je hodin?\u201c"],t.s)
B.bkR=new A.a6(B.aF,B.ahz,!1)
B.axV=new A.aQ("Nela se pod\xedv\xe1 na mobil.")
B.an5=s(["\u201eNev\xedm. Mobily ukazuj\xed 00:00, vypad\xe1 to, \u017ee se zasekly.\u201c"],t.s)
B.bmJ=new A.a6(B.b3,B.an5,!1)
B.arp=s(["\u201ePo\u0159\xe1d p\u016flnoc? To je zvl\xe1\u0161tn\xed. Kdy\u017e mne sem n\u011bkdo zav\u0159el, zastavily se v\u0161echny hodiny p\u0159esn\u011b o p\u016flnoci. Bim, bam! Kukuk! Pardon. To se mi te\u010f n\u011bjak st\xe1v\xe1.\u201c"],t.s)
B.bn8=new A.a6(B.aF,B.arp,!1)
B.axO=new A.aQ("Jon\xe1\u0161 uk\xe1\u017ee na z\xe1st\u011bru.")
B.ajX=s(["\u201eTady m\xe1te jmenovku. \u201aMistr Vav\u0159inec Tikal, hodin\xe1\u0159 muzea.\u2018\u201c"],t.s)
B.blj=new A.a6(B.aY,B.ajX,!1)
B.anw=s(["\u201eVav\u0159inec Tikal! No jist\u011b, to jsem j\xe1! J\xe1 tu\u0161il, \u017ee m\xe1m n\u011bco spole\u010dn\xe9ho s hodinami.\u201c"],t.s)
B.bkA=new A.a6(B.aF,B.anw,!1)
B.anl=s([B.ay7,B.bkR,B.axV,B.bmJ,B.bn8,B.axO,B.blj,B.bkA],t.a)
B.bpa=new A.cq("story_12",B.anl)
B.arF=s(["\u201eV. T.! To vy jste napsal ten vzkaz!\u201c"],t.s)
B.bl0=new A.a6(B.aQ,B.arF,!1)
B.axr=new A.aQ("Jon\xe1\u0161 mu uk\xe1\u017ee vzkaz ze \u0161atny. Hodin\xe1\u0159 zbledne.")
B.aqP=s(["\u201eTo je opravdu moje p\xedsmo. Krasopis! Jedni\u010dka s hv\u011bzdi\u010dkou! Ale kdy bych to psal? A pro\u010d?\u201c"],t.s)
B.bmI=new A.a6(B.aF,B.aqP,!1)
B.aez=s(["\u201eA kdo v\xe1s zav\u0159el?\u201c"],t.s)
B.bmW=new A.a6(B.aQ,B.aez,!1)
B.apW=s(["\u201eJedna pan\xed. Byla kr\xe1sn\xe1, ale hrozn\u011b unaven\xe1. Nab\xeddla mi \u0161\xe1lek \u010daje a pak\u2026 u\u017e si nepamatuju nic, jen to, jak se usm\xedvala.\u201c"],t.s)
B.bl7=new A.a6(B.aF,B.apW,!1)
B.axd=new A.aQ("V\u0161ichni se na sebe pod\xedvaj\xed. Nikdo nic ne\u0159ekne. Ale ka\u017ed\xfd mysl\xed na tot\xe9\u017e. Hodin\xe1\u0159 se zvedne, opr\xe1\u0161\xed si z\xe1st\u011bru a zam\xed\u0159\xed s nimi k hlavn\xedmu s\xe1lu. P\u0159ed n\xedm v\u0161ak jsou ryt\xed\u0159i v pln\xe9 zbroji. Stoj\xed bok po boku a nikoho nepust\xed d\xe1l.")
B.aiQ=s(["\u201eAch, p\xe1nov\xe9 ryt\xed\u0159i. Velmi d\u016fstojn\xed. A velmi tvrdohlav\xed.\u201c"],t.s)
B.bnm=new A.a6(B.aF,B.aiQ,!1)
B.axK=new A.aQ("Nela zaklepe na brn\u011bn\xed.")
B.aeS=s(["\u201eHal\xf3\xf3\xf3? Je tam n\u011bkdo?\u201c"],t.s)
B.bkQ=new A.a6(B.b3,B.aeS,!1)
B.axg=new A.aQ("Brn\u011bn\xed dut\u011b zadun\xed. Ale \u017e\xe1dn\xfd z nich se ani nehne.")
B.akx=s([B.bl0,B.axr,B.bmI,B.bmW,B.bl7,B.axd,B.bnm,B.axK,B.bkQ,B.axg],t.a)
B.boQ=new A.cq("story_13",B.akx)
B.ay0=new A.aQ("Ryt\xed\u0159i jeden po druh\xe9m zasalutuj\xed a ustoup\xed stranou.")
B.ajM=s(["\u201eOni n\xe1m zasalutovali! Vid\u011bli jste to? Zasalutovali!\u201c"],t.s)
B.blv=new A.a6(B.aQ,B.ajM,!1)
B.arY=s(["\u201eRyt\xed\u0159sk\xe1 \u010dest. Pozor! Pohov! R\xe1z, dva, r\xe1z, dva! J\xe1 bych byl dobr\xfd ryt\xed\u0159. Jen by m\u011b ta zbroj tla\u010dila.\u201c"],t.s)
B.bkO=new A.a6(B.aF,B.arY,!1)
B.af2=s(["\u201eJe v po\u0159\xe1dku?\u201c"],t.s)
B.bnU=new A.a6(B.b3,B.af2,!1)
B.as6=s(["\u201eTen \u010daj byl asi hodn\u011b siln\xfd.\u201c"],t.s)
B.bmh=new A.a6(B.aY,B.as6,!1)
B.ax1=new A.aQ("V\u0161ichni pokra\u010duj\xed d\xe1l do obrovsk\xe9ho s\xe1lu. Je v n\u011bm \u0161ero a podlaha pod nohama zlov\u011bstn\u011b vr\u017ee.")
B.aja=s(["\u201eTuhle podlahu jsem\u2026 opravoval. Nebo jsem ji\u2026 hmm. Tady bych na va\u0161em m\xedst\u011b \u0161el opatrn\u011b. Nev\xedm pro\u010d. Ale \u0161el bych.\u201c"],t.s)
B.bmv=new A.a6(B.aF,B.aja,!1)
B.afS=s(["\u201eTo je stra\u0161n\u011b uklid\u0148uj\xedc\xed.\u201c"],t.s)
B.bku=new A.a6(B.b3,B.afS,!1)
B.ah4=s([B.ay0,B.blv,B.bkO,B.bnU,B.bmh,B.ax1,B.bmv,B.bku],t.a)
B.bp3=new A.cq("story_14",B.ah4)
B.axo=new A.aQ("Deska se ot\u0159ese a pole se jedno po druh\xe9m propadaj\xed do tmy. K\u016f\u0148 stihne na posledn\xed chv\xedli odsko\u010dit do bezpe\u010d\xed. Z temn\xe9 j\xe1my vylet\xed zlat\xfd \xfalomek kl\xed\u010de se \u0161t\xedtem.")
B.ai5=s(["\u201eBum! To byla ale kr\xe1sa!\u201c"],t.s)
B.bnX=new A.a6(B.aF,B.ai5,!1)
B.ayu=new A.aQ("V\u0161ichni se na n\u011bj pod\xedvaj\xed.")
B.adJ=s(["\u201e\u2026Ehm. Pardon. Chci \u0159\xedct: to bylo velmi nebezpe\u010dn\xe9.\u201c"],t.s)
B.blo=new A.a6(B.aF,B.adJ,!1)
B.apK=s(["\u201eA dal\u0161\xed kus.\u201c"],t.s)
B.blp=new A.a6(B.aY,B.apK,!1)
B.aqx=s(["\u201eA kolik jich jako je\u0161t\u011b m\xe1 b\xfdt?\u201c"],t.s)
B.bkS=new A.a6(B.b3,B.aqx,!1)
B.ayp=new A.aQ("Hodin\xe1\u0159 prom\u011b\u0159uje \xfalomek lupou.")
B.ajq=s(["\u201eKl\xed\u010d\u2026 To je moje pr\xe1ce. Tenhle kl\xed\u010d jsem kdysi vyrobil. Pro\u010d je ulomen\xfd? Kdo by\u2026 Ach ne.\u201c"],t.s)
B.bna=new A.a6(B.aF,B.ajq,!1)
B.abC=s([B.axo,B.bnX,B.ayu,B.blo,B.blp,B.bkS,B.ayp,B.bna],t.a)
B.boP=new A.cq("story_15",B.abC)
B.ayM=new A.aQ("Cesta k dal\u0161\xedmu s\xe1lu vede p\u0159es vstupn\xed halu. Kolem obrazu baronky proch\xe1zej\xed po \u0161pi\u010dk\xe1ch. Jon\xe1\u0161 se nechce d\xedvat, ale nakonec se stejn\u011b pod\xedv\xe1. Obraz je pr\xe1zdn\xfd. Z\u016fstalo jen osam\u011bl\xe9 k\u0159eslo.")
B.aq4=s(["\u201eKde je?\u201c"],t.s)
B.bnI=new A.a6(B.aY,B.aq4,!1)
B.ays=new A.aQ("Jon\xe1\u0161 mrkne. A baronka je zase zp\u011bt v obraze. Sp\xed a usm\xedv\xe1 se\u2026")
B.akw=s(["\u201eTo je ona. Pan\xed baronka.\u201c"],t.s)
B.bm7=new A.a6(B.aF,B.akw,!1)
B.apJ=s(["\u201eTo ona je ta pan\xed s \u010dajem? Ona v\xe1s zav\u0159ela?\u201c"],t.s)
B.blm=new A.a6(B.aQ,B.apJ,!1)
B.ag8=s(["\u201eMo\u017en\xe1\u2026 Nev\xedm. Moje hlava je sam\xe1 d\xedra\u2026 jako ement\xe1l.\u201c"],t.s)
B.bnH=new A.a6(B.aF,B.ag8,!1)
B.ag0=s(["\u201eAle vy jste p\u0159ece ten kl\xed\u010d vyrobil. Kdy\u017e si vzpomenete, zjist\xedme, kde je zbytek!\u201c"],t.s)
B.bkT=new A.a6(B.aQ,B.ag0,!1)
B.apl=s(["\u201eAlchymista m\u011bl naho\u0159e ve v\u011b\u017ei svou laborato\u0159. On m\u011bl v\u017edycky l\xe9k na v\u0161echno.\u201c"],t.s)
B.bll=new A.a6(B.aF,B.apl,!1)
B.akd=s(["\u201eDob\u0159e, jdeme tam.\u201c"],t.s)
B.blZ=new A.a6(B.aQ,B.akd,!1)
B.ay1=new A.aQ("Hodin\xe1\u0159 vede d\u011bti po to\u010dit\xfdch schodech nahoru do v\u011b\u017ee, do laborato\u0159e star\xe9ho alchymisty. V laborato\u0159i je ticho a v\u0161ude le\u017e\xed prach.")
B.ad4=s(["\u201eTak, pane alchymisto. Kde m\xe1te ten l\xe9k na v\u0161echno?\u201c"],t.s)
B.blq=new A.a6(B.aQ,B.ad4,!1)
B.aeu=s([B.ayM,B.bnI,B.ays,B.bm7,B.blm,B.bnH,B.bkT,B.bll,B.blZ,B.ay1,B.blq],t.a)
B.bpf=new A.cq("story_16",B.aeu)
B.axF=new A.aQ("V knize jsou t\u0159i recepty. Tenebrikus je lektvar no\u010dn\xedho vid\u011bn\xed. Ardeon je lektvar odvahy. A Siderion je elix\xedr hv\u011bzdn\xe9ho sv\u011btla. Pod n\xe1zvem je drobn\xe9 p\xedsmo.")
B.ait=s(["\u201e\u201aRozjasn\xed mysl a vr\xe1t\xed ztracen\xe9 vzpom\xednky. Spr\xe1vn\xfd postup je ve hv\u011bzd\xe1ch. Polovina d\xe1vky rozjasn\xed mysl. Cel\xe1 d\xe1vka usp\xed na sto let.\u2018\u201c"],t.s)
B.bnb=new A.a6(B.aY,B.ait,!1)
B.axb=new A.aQ("Kdy\u017e se obr\xe1t\xed posledn\xed list, le\u017e\xed na n\u011bm zlat\xfd \xfalomek kl\xed\u010de s hv\u011bzdou.")
B.arg=s(["\u201eDal\u0161\xed kus kl\xed\u010de! A k tomu recept na pam\u011b\u0165. Dneska m\xe1me \u0161\u0165astn\xfd den.\u201c"],t.s)
B.bm6=new A.a6(B.aQ,B.arg,!1)
B.apd=s(["\u201eEmo, jsme zav\u0159en\xed v muzeu.\u201c"],t.s)
B.blu=new A.a6(B.b3,B.apd,!1)
B.ai8=s(["\u201e\u0160\u0165astn\xfd den v r\xe1mci mo\u017enost\xed.\u201c"],t.s)
B.bnB=new A.a6(B.aQ,B.ai8,!1)
B.aod=s(["\u201e\u201aSpr\xe1vn\xfd postup je ve hv\u011bzd\xe1ch.\u2018 Hv\u011bzdy ale odsud v\u016fbec nejsou vid\u011bt.\u201c"],t.s)
B.bnd=new A.a6(B.aY,B.aod,!1)
B.axC=new A.aQ("Nela uk\xe1\u017ee na \xfazk\xe9 sch\u016fdky v rohu.")
B.all=s(["\u201eCo zkusit schody?\u201c"],t.s)
B.bmk=new A.a6(B.b3,B.all,!1)
B.axa=new A.aQ("Sch\u016fdky vedou a\u017e na sam\xfd vrchol v\u011b\u017ee, do mal\xe9 hv\u011bzd\xe1rny. Za velk\xfdm oknem z\xe1\u0159\xed tis\xedce hv\u011bzd.")
B.adV=s(["\u201eV\u017edy\u0165 je tu milion hv\u011bzd. Co s t\xedm m\xe1me d\u011blat?\u201c"],t.s)
B.ble=new A.a6(B.aY,B.adV,!1)
B.aoi=s([B.axF,B.bnb,B.axb,B.bm6,B.blu,B.bnB,B.bnd,B.axC,B.bmk,B.axa,B.ble],t.a)
B.bp4=new A.cq("story_17",B.aoi)
B.ayz=new A.aQ("Souhv\u011bzd\xed na obloze se rozz\xe1\u0159\xed a do v\u011b\u017ee padne st\u0159\xedbrn\xe9 hv\u011bzdn\xe9 sv\u011btlo. Pomalu sklouzne po schodech dol\u016f, a\u017e do alchymistovy laborato\u0159e.")
B.acd=s(["\u201eTak\u017ee te\u010f asi ty hv\u011bzdy sv\xedt\xed spr\xe1vn\u011b. Kdo by \u0159ekl, \u017ee jdou hv\u011bzdy zapnout.\u201c"],t.s)
B.bnj=new A.a6(B.b3,B.acd,!1)
B.axe=new A.aQ("D\u011bti jdou za sv\u011btlem do laborato\u0159e.")
B.ajW=s(["\u201eMn\u011b se to tu nel\xedb\xed. N\u011bkdo n\xe1s tu nechce, c\xedt\xedm to.\u201c"],t.s)
B.bmc=new A.a6(B.aY,B.ajW,!1)
B.afL=s(["\u201eAlchymista m\xedval v\u0161echno p\u0159ipraven\xe9 dop\u0159edu. Jestli ten l\xe9k n\u011bkde bude, tak ur\u010dit\u011b tady.\u201c"],t.s)
B.bmd=new A.a6(B.aF,B.afL,!1)
B.an8=s([B.ayz,B.bnj,B.axe,B.bmc,B.bmd],t.a)
B.bpi=new A.cq("story_18",B.an8)
B.axN=new A.aQ("Hodin\xe1\u0159 vypije odm\u011b\u0159enou polovinu elix\xedru. \u0160kytne a v o\u010d\xedch mu zajisk\u0159\xed drobn\xe9 hv\u011bzdi\u010dky.")
B.ane=s(["\u201eLevandule! Ten \u010daj byl levandulov\xfd. A ona \u0159\xedkala: \u201aBu\u010fte tak laskav, mist\u0159e Tikale. Jenom zastavte hodiny. Jenom na chvilku.\u2018 Potom za\u0161eptala: \u201aJenom nav\u017edy.\u2018 Myslel jsem, \u017ee jsem \u0161patn\u011b rozum\u011bl. A pak\u2026 u\u017e si nic nepamatuju.\u201c"],t.s)
B.bmi=new A.a6(B.aF,B.ane,!1)
B.akp=s(["\u201eJak\xe9 hodiny?\u201c"],t.s)
B.bm5=new A.a6(B.aY,B.akp,!1)
B.ah6=s(["\u201eTo je\u0161t\u011b nev\xedm. Ale v\xedm, kde to zjist\xedme.\u201c"],t.s)
B.bkL=new A.a6(B.aF,B.ah6,!1)
B.ayF=new A.aQ("Druhou polovinu elix\xedru hodin\xe1\u0159 pe\u010dliv\u011b zaz\xe1tkuje a schov\xe1 do kapsy z\xe1st\u011bry.")
B.aje=s(["\u201eNa hor\u0161\xed \u010dasy.\u201c"],t.s)
B.bkF=new A.a6(B.aF,B.aje,!1)
B.ayG=new A.aQ("V tu chv\xedli se ze schodi\u0161t\u011b pod nimi oz\xfdv\xe1 tich\xe9 \u0161ust\u011bn\xed. Pomal\xfdmi kroky jde n\u011bkdo nahoru. V d\xe1lce se oz\xfdv\xe1 ospal\xfd hlas:")
B.anE=s(["\u201eWas ist das\u2026? Kdo m\u011b to zase ru\u0161\xed\u2026? Ruhe\u2026 Ruhe\u2026\u201c"],t.s)
B.bmS=new A.a6(B.xS,B.anE,!0)
B.afv=s([B.axN,B.bmi,B.bm5,B.bkL,B.ayF,B.bkF,B.ayG,B.bmS],t.a)
B.bp8=new A.cq("story_19",B.afv)
B.ayC=new A.aQ("Kroky se zastav\xed za dve\u0159mi a v\u0161ichni ztuhnou. Ozve se jen dlouh\xe9, ospal\xe9 z\xedvnut\xed. Pak \u0161ust\u011bn\xed sukn\xed pomalu sl\xe1bne, a\u017e utichne \xfapln\u011b.")
B.ank=s(["\u201eJe pry\u010d. Vr\xe1tila se do obrazu. O\u010dividn\u011b moc dlouho venku nevydr\u017e\xed.\u201c"],t.s)
B.bkN=new A.a6(B.aY,B.ank,!1)
B.aix=s(["\u201eTak toho vyu\u017eijeme. Rychle dol\u016f!\u201c"],t.s)
B.bmN=new A.a6(B.aQ,B.aix,!1)
B.axW=new A.aQ("D\u011bti jdou tmou za hodin\xe1\u0159em. Vede je dlouhou chodbou a\u017e k n\xedzk\xfdm dve\u0159\xedm.")
B.age=s(["\u201eMoje d\xedlna! Kdo mi tady ud\u011blal takov\xfd nepo\u0159\xe1dek? Aha. J\xe1. Tady b\xfdval v\u017edycky po\u0159\xe1dek. Ka\u017ed\xe9 hodiny v\u011bd\u011bly, kolik je hodin. Te\u010f nev\u011bd\xed nic. Ani jedny. Jako j\xe1.\u201c"],t.s)
B.bkW=new A.a6(B.aF,B.age,!1)
B.ap8=s([B.ayC,B.bkN,B.bmN,B.axW,B.bkW],t.a)
B.boZ=new A.cq("story_20",B.ap8)
B.ax2=new A.aQ("N\xe1st\u011bnn\xe9 hodiny odbij\xed p\u016flnoc a v\u0161echny bud\xedky se ozvou s nimi. Zvon\xed, cinkaj\xed a rachot\xed. Pak v\u0161echny zase ztichnou a ru\u010di\u010dky se znovu zastav\xed. A na podlaze pod pracovn\xedm stolem n\u011bco le\u017e\xed.")
B.arL=s(["\u201eMoje bed\xfdnka! Moje sou\u010d\xe1stky! Pades\xe1t let jsem je t\u0159\xeddil!\u201c"],t.s)
B.blb=new A.a6(B.aF,B.arL,!1)
B.ay2=new A.aQ("Hodin\xe1\u0159 si k bed\xfdnce klekne a n\u011b\u017en\u011b ji hlad\xed.")
B.agP=s(["\u201eTahle bed\xfdnka byla v\u017edycky na sv\xe9m m\xedst\u011b. A v\u0161echno v n\xed taky.\u201c"],t.s)
B.bls=new A.a6(B.aF,B.agP,!1)
B.alm=s([B.ax2,B.blb,B.ay2,B.bls],t.a)
B.bpk=new A.cq("story_21",B.alm)
B.axR=new A.aQ("Posledn\xed sou\u010d\xe1stka zapadne na sv\xe9 m\xedsto a pod bed\xfdnkou se zaleskne zlat\xfd \xfalomek kl\xed\u010de s kole\u010dkem. Hodin\xe1\u0159 vezme bed\xfdnku do rukou. Chv\xedli se na ni d\xedv\xe1. A pak se mu v o\u010d\xedch rozsv\xedt\xed. Tentokr\xe1t doopravdy.")
B.afn=s(["\u201eU\u017e si vzpom\xedn\xe1m. Na v\u0161echno. Za orlojem je tajn\xe1 chodba, kter\xe1 vede k srdci muzea.\u201c"],t.s)
B.bnf=new A.a6(B.aF,B.afn,!1)
B.asc=s(["\u201eBaronka m\u011b p\u0159inutila ho zastavit a zape\u010detit. Od t\xe9 chv\xedle je tu po\u0159\xe1d p\u016flnoc. R\xe1no nikdy nep\u0159ijde a dve\u0159e se nikdy neotev\u0159ou.\u201c"],t.s)
B.bkl=new A.a6(B.aF,B.asc,!1)
B.apF=s(["\u201eA kl\xed\u010d?\u201c"],t.s)
B.bkE=new A.a6(B.aY,B.apF,!1)
B.ahY=s(["\u201eTen rozlomila ona. Kousek po kousku roznesla \xfalomky po muzeu a u ka\u017ed\xe9ho nastra\u017eila past, aby u\u017e nikdo nemohl srdce muzea znovu probudit. A j\xe1 hlup\xe1k j\xed je\u0161t\u011b sv\xedtil na cestu.\u201c"],t.s)
B.blM=new A.a6(B.aF,B.ahY,!1)
B.abF=s(["\u201eJen jednou se mi na chv\xedli rozjasnilo v hlav\u011b. Rychle jsem napsal vzkaz a schoval ho do sk\u0159\xed\u0148ky v \u0161atn\u011b, kde by ho baronka nikdy nehledala. Stihl jsem to t\u011bsn\u011b p\u0159edt\xedm, ne\u017e mi poru\u010dila, a\u0165 se zav\u0159u za m\u0159\xed\u017e. A pak u\u017e jsem si nepamatoval nic.\u201c"],t.s)
B.blB=new A.a6(B.aF,B.abF,!1)
B.arR=s(["\u201eAle pro\u010d to ud\u011blala?\u201c"],t.s)
B.bm0=new A.a6(B.aQ,B.arR,!1)
B.ah5=s([B.axR,B.bnf,B.bkl,B.bkE,B.blM,B.blB,B.bm0],t.a)
B.bph=new A.cq("story_22",B.ah5)
B.apL=s(["\u201eZ\xedtra r\xe1no ji maj\xed odv\xe9zt do nov\xe9 galerie na n\xe1dra\u017e\xed. Mezi vlaky, hl\xe1\u0161en\xed a tis\xedce lid\xed. L\xe9ta tady nem\u016f\u017ee usnout kv\u016fli n\xe1v\u0161t\u011bvn\xedk\u016fm. A tam by neusnula u\u017e nikdy.\u201c"],t.s)
B.blP=new A.a6(B.aF,B.apL,!1)
B.aj9=s(["\u201eTo je vlastn\u011b\u2026 trochu smutn\xe9.\u201c"],t.s)
B.bkK=new A.a6(B.aQ,B.aj9,!1)
B.apx=s(["\u201eJen\u017ee j\xed je \xfapln\u011b jedno, \u017ee tu n\u011bkoho zamkne. A \u017ee se muzeum u\u017e nikdy neotev\u0159e. To je teda p\u011bkn\u011b sobeck\xe9.\u201c"],t.s)
B.bmY=new A.a6(B.b3,B.apx,!1)
B.axH=new A.aQ("Hodin\xe1\u0159 je zavede do rohu d\xedlny. Stoj\xed tam orloj, na kter\xe9m hodin\xe1\u0159 pracoval cel\xfd \u017eivot. Te\u010f ml\u010d\xed.")
B.aiI=s(["\u201eMoje nejkr\xe1sn\u011bj\u0161\xed pr\xe1ce. A cesta k srdci muzea. Jen\u017ee jsem ho musel rozebrat.\u201c"],t.s)
B.bkH=new A.a6(B.aF,B.aiI,!1)
B.amU=s(["\u201eTak to oprav\xedme. Ur\u010dit\u011b to nebude t\u011b\u017ek\xe9.\u201c"],t.s)
B.bmU=new A.a6(B.aQ,B.amU,!1)
B.ag6=s(["\u201eTo sam\xe9 jsi \u0159\xedkala o tom pl\xe1nu se \u0161atnou. A pod\xedvej, kde jsme.\u201c"],t.s)
B.bnJ=new A.a6(B.b3,B.ag6,!1)
B.akr=s([B.blP,B.bkK,B.bmY,B.axH,B.bkH,B.bmU,B.bnJ],t.a)
B.bp2=new A.cq("story_23",B.akr)
B.axE=new A.aQ("Orloj se nadechne. Ru\u010di\u010dky se rozeb\u011bhnou a dv\xed\u0159ka dole se pomalu otev\u0159ou. Za nimi je \xfazk\xe1 chodba a na jej\xedm konci podivn\xe9 sv\u011btlo.")
B.aqR=s(["\u201eTajn\xe1 chodba! Poj\u010fte!\u201c"],t.s)
B.bmp=new A.a6(B.aQ,B.aqR,!1)
B.ayt=new A.aQ("Chodba za orlojem kon\u010d\xed ve skryt\xe9 hale s vysok\xfdm stropem. Uprost\u0159ed zdi vis\xed obrovsk\xe9 hodiny, p\u0159es cifern\xedk maj\xed rudou pe\u010de\u0165.")
B.aoY=s(["\u201eSrdce muzea.\u201c"],t.s)
B.bmR=new A.a6(B.aF,B.aoY,!1)
B.axJ=new A.aQ("Za jejich z\xe1dy za\u0161ust\xed \u0161aty.")
B.ayI=new A.aQ("Ve dve\u0159\xedch haly stoj\xed baronka Frida von Schlafenberg. Skute\u010dn\xe1 a \u017eiv\xe1, vystoupila z obrazu. Je mnohem vy\u0161\u0161\xed, ne\u017e si mysleli. A hrozn\u011b, hrozn\u011b ospal\xe1.")
B.anf=s(["\u201eKinder\u2026 D\u011bti. Pro\u010d jste tak hlu\u010dn\xe9? Sto let. Sto let jsem neusnula. Nechte ty hodiny sp\xe1t. Bitte\u2026\u201c"],t.s)
B.bly=new A.a6(B.xS,B.anf,!1)
B.ayx=new A.aQ("Ema ud\u011bl\xe1 krok dop\u0159edu a postav\xed se p\u0159ed ostatn\xed. Baronka k n\xed nat\xe1hne ruku. Ale v p\u016fli pohybu se j\xed zav\u0159ou o\u010di. Pomalu se sesune na schod, polo\u017e\xed hlavu na ruku\u2026 a usne. Jej\xed postava zbledne, zpr\u016fhledn\xed a rozplyne se.")
B.aj4=s(["\u201eVr\xe1tila se do obrazu?\u201c"],t.s)
B.bma=new A.a6(B.b3,B.aj4,!1)
B.afX=s(["\u201eVypad\xe1 to tak. Ale nev\xedme, na jak dlouho.\u201c"],t.s)
B.blA=new A.a6(B.aY,B.afX,!1)
B.agU=s(["\u201eTak si mus\xedme posp\xed\u0161it. Pom\u016f\u017eete star\xe9mu hodin\xe1\u0159i? Je\u0161t\u011b naposledy?\u201c"],t.s)
B.blS=new A.a6(B.aF,B.agU,!1)
B.as7=s([B.axE,B.bmp,B.ayt,B.bmR,B.axJ,B.ayI,B.bly,B.ayx,B.bma,B.blA,B.blS],t.a)
B.boI=new A.cq("story_24",B.as7)
B.axG=new A.aQ("\xdalomky se zatav\xed do vosku a pe\u010de\u0165 se rozz\xe1\u0159\xed. Pak praskne a rozlet\xed se na kusy. Pod n\xed se objev\xed cifern\xedk. Ru\u010di\u010dky ukazuj\xed p\u016flnoc. Hodiny se zhluboka nadechnou\u2026 a rozb\u011bhnou se. Po cel\xe9m muzeu se rozezn\xed tik\xe1n\xed v\u0161ech hodin najednou. Ru\u010di\u010dky ute\u010dou od p\u016flnoci, v okn\u011b chodby je vid\u011bt \xfasvit a z\xe1mky v\u0161ech dve\u0159\xed v muzeu cvaknou.")
B.apa=s(["\u201eSly\u0161\xedte to? Muzeum zase d\xfdch\xe1. Srdce muzea je tajemstv\xed, nikdo ho tu nesm\xed naj\xedt a v\xe1s tak\xe9 ne. Tuhle chodbu zase schov\xe1m. Z\u016fstanu tady a d\xe1m do po\u0159\xe1dku v\u0161echno, co tu baronka provedla. Hodiny u\u017e nikomu nedovol\xedm zastavit. Ani za \u0161\xe1lek levandulov\xe9ho \u010daje.\u201c"],t.s)
B.bmr=new A.a6(B.aF,B.apa,!1)
B.anQ=s(["\u201eA posp\u011b\u0161te si. Baronka te\u010f tvrd\u011b sp\xed. Ale dokud je muzeum zav\u0159en\xe9, m\u016f\u017ee kdykoli vystoupit z obrazu. Otev\u0159ete hlavn\xed dve\u0159e, ne\u017e se vzbud\xed.\u201c"],t.s)
B.blR=new A.a6(B.aF,B.anQ,!1)
B.ajt=s([B.axG,B.bmr,B.blR],t.a)
B.boB=new A.cq("story_25",B.ajt)
B.ayi=new A.aQ("Ema ho obejme. Jon\xe1\u0161 mu pod\xe1 ruku. Nela mu vyt\xe1hne pavu\u010dinu z vlas\u016f. Zvenku se ozve motor n\xe1kladn\xedho auta, st\u011bhov\xe1ci p\u0159ijeli pro obraz baronky. D\u011bti b\u011b\u017e\xed zp\xe1tky do vstupn\xed haly. Baronka v obraze sp\xed a usm\xedv\xe1 se. Jen\u017ee hlavn\xed dve\u0159e se po\u0159\xe1d nehnou.")
B.agY=s(["\u201eZ\xe1mky p\u0159ece cvakly. Tak pro\u010d se ty dve\u0159e neotev\u0159ou?\u201c"],t.s)
B.bni=new A.a6(B.b3,B.agY,!1)
B.apR=s(["\u201eH\xe1d\xe1m, \u017ee tohle je posledn\xed past pan\xed baronky.\u201c"],t.s)
B.blQ=new A.a6(B.aQ,B.apR,!1)
B.axS=new A.aQ("Baronka v obraze se zavrt\xed a ze span\xed vzdychne. D\u011bti ztuhnou.")
B.agA=s(["\u201eRychle. A potichu.\u201c"],t.s)
B.bnD=new A.a6(B.aQ,B.agA,!1)
B.aji=s([B.ayi,B.bni,B.blQ,B.axS,B.bnD],t.a)
B.bpg=new A.cq("story_26",B.aji)
B.ayK=new A.aQ("Posledn\xed z\xe1str\u010dka cvakne. T\u011b\u017ek\xe1 k\u0159\xeddla dve\u0159\xed se pomalu otev\u0159ou a do haly vtrhne rann\xed sv\u011btlo. Rozlije se po podlaze, po zdech a nakonec dopadne i na obraz.")
B.akO=s(["\u201eJe otev\u0159eno! Muzeum je otev\u0159en\xe9!\u201c"],t.s)
B.bnq=new A.a6(B.aQ,B.akO,!1)
B.ajj=s(["\u201ePod\xedvejte na obraz. Pan\xed baronce n\u011bjak ztuhl \xfasm\u011bv.\u201c"],t.s)
B.bmE=new A.a6(B.b3,B.ajj,!1)
B.axc=new A.aQ("Tv\xe1\u0159 baronky se pomalu zamra\u010d\xed. U\u017e se nepohne.")
B.ai4=s(["\u201eTak to bychom m\u011bli. A te\u010f honem pry\u010d, ne\u017e n\xe1s tu n\u011bkdo najde.\u201c"],t.s)
B.blf=new A.a6(B.aY,B.ai4,!1)
B.axT=new A.aQ("D\u011bti vyklouznou z muzea ve chv\xedli, kdy st\u011bhov\xe1ci vystupuj\xed z auta.")
B.aqA=s(["\u201eZvl\xe1dli jsme to!\u201c"],t.s)
B.bm9=new A.a6(B.aQ,B.aqA,!1)
B.axD=new A.aQ("St\u011bhov\xe1ci vejdou do muzea, po chv\xedli vyn\xe1\u0161\xed velk\xfd obraz zabalen\xfd do deky. Jeden roh deky sklouzne.")
B.axz=new A.aQ("Baronka Frida von Schlafenberg sice sp\xed, ale tv\xe1\u0159\xed se tak na\u0161tvan\u011b jako je\u0161t\u011b nikdy. V\u0161imnou si toho i st\u011bhov\xe1ci. \u201eNa n\xe1dra\u017e\xed si zvykne,\u201c prohod\xed jeden ze st\u011bhov\xe1k\u016f. Potom, co auto odjede, se v okn\u011b muzea na okam\u017eik objev\xed star\xfd hodin\xe1\u0159 s lampou. K\xfdvne na n\u011b, zamrk\xe1 a zmiz\xed. Z muzea je sly\u0161et tich\xe9, spokojen\xe9 tik\xe1n\xed.")
B.aqJ=s(["\u201eTohle n\xe1m nikdo neuv\u011b\u0159\xed.\u201c"],t.s)
B.bnp=new A.a6(B.b3,B.aqJ,!1)
B.alc=s([B.ayK,B.bnq,B.bmE,B.axc,B.blf,B.axT,B.bm9,B.axD,B.axz,B.bnp],t.a)
B.boR=new A.cq("story_27",B.alc)
B.agq=s([B.boT,B.boM,B.bp_,B.bp0,B.bpj,B.bpe,B.boW,B.boX,B.boL,B.bpc,B.boH,B.bpa,B.boQ,B.bp3,B.boP,B.bpf,B.bp4,B.bpi,B.bp8,B.boZ,B.bpk,B.bph,B.bp2,B.boI,B.boB,B.bpg,B.boR],t.WD)
