B.agx=s([B.Q4,B.b36,B.b38],t.u)
B.bBJ=new A.bq(1,"vrznut\xedm","sfx_story_locker_creak",null,1)
B.bAW=new A.bq(1,"vypadne","sfx_story_scroll_drop",null,1)
B.bBH=new A.bq(5,"\u0161ust\u011bn\xed","sfx_story_skirts",null,1)
