B.bcQ=new A.aF("sfx_t03_pile_reveal",0.001,1,null,1)
B.ahV=s([B.bcQ],t.e)
B.bqm=new A.hf("Pod\xedvej se, co u\u017e v m\u0159\xed\u017ece le\u017e\xed. Najde\u0161, jak\xe9 to m\xe1 pravidlo?","Tady plat\xed, \u017ee jedna sou\u010d\xe1stka m\u016f\u017ee b\xfdt v ka\u017ed\xe9m sloupci a \u0159\xe1dku jen jednou. Zlat\u011b sv\xedt\xed dal\u0161\xed krok.")
B.ahW=s([B.bqm],t.AE)
B.ayg=new A.aQ("D\u011bda Bohou\u0161 slav\xed sedmdes\xe1tiny a d\u016fm prask\xe1 ve \u0161vech. Von\xed tu j\xeddlo, cinkaj\xed skleni\u010dky a po\u0159\xe1d n\u011bkdo zvon\xed u dve\u0159\xed. Teta Jarmila \u0161t\xedpe do tv\xe1\u0159\xed ka\u017ed\xe9ho, kdo se nestihne schovat. Str\xfdc Pepa po\u0159\xe1d dokola vypr\xe1v\xed o hypot\xe9k\xe1ch. A d\u011bda spokojen\u011b sed\xed v \u010dele stolu a usm\xedv\xe1 se.")
B.bE=new A.kq("klara","assets/images/stories/bohous/story/portrait_klara.webp")
B.agQ=s(["\u201eTohle je ofici\xe1ln\u011b nejnudn\u011bj\u0161\xed oslava na sv\u011bt\u011b. M\xe1m to spo\u010d\xedtan\xe9. Str\xfdc \u0159ekl \u201ahypot\xe9ka\u2018 dvaa\u010dty\u0159icetkr\xe1t.\u201c"],t.s)
B.bnw=new A.a6(B.bE,B.agQ,!1)
B.bb=new A.kq("tobi","assets/images/stories/bohous/story/portrait_tobi.webp")
B.alJ=s(["\u201eTeta m\u011b \u0161t\xedpla p\u011btkr\xe1t. Za chv\xedli budu m\xedt m\xedsto tv\xe1\u0159\xed dv\u011b raj\u010data.\u201c"],t.s)
B.bmt=new A.a6(B.bb,B.alJ,!1)
B.ao0=s(["\u201eDv\u011b mal\xe1 kysel\xe1 raj\u010d\xe1tka.\u201c"],t.s)
B.bnu=new A.a6(B.bE,B.ao0,!1)
B.aq8=s(["\u201eJ\xe1 nejsem kysel\xfd!\u201c"],t.s)
B.blC=new A.a6(B.bb,B.aq8,!1)
B.axp=new A.aQ("Pod stolem si povzdechne pes Ferda. Nikdo mu zat\xedm neupustil ani drobe\u010dek. Kl\xe1ra k\xfdvne na bratra Tobiho a uk\xe1\u017ee ke schod\u016fm.")
B.ajT=s(["\u201eMiz\xedme.\u201c"],t.s)
B.bnN=new A.a6(B.bE,B.ajT,!1)
B.axn=new A.aQ("Schody vedou na p\u016fdu, kam nikdo nechod\xed.")
B.apQ=s([B.ayg,B.bnw,B.bmt,B.bnu,B.blC,B.axp,B.bnN,B.axn],t.a)
B.bp7=new A.cq("story_01",B.apQ)
B.ayf=new A.aQ("Na p\u016fd\u011b je \u0161ero a v\u0161ude prach. Uprost\u0159ed stoj\xed star\xe1 bedna s velk\xfdm \u010derven\xfdm B.")
B.alo=s(["\u201e\u201aNE-O-TE-V\xcd-RAT!\u2018 A pod t\xedm malink\xfdmi p\xedsmenky: \u201akrom\u011b pr\u016fzkumn\xedk\u016f\u2018.\u201c"],t.s)
B.blz=new A.a6(B.bb,B.alo,!1)
B.aqo=s(["\u201ePr\u016fzkumn\xedci. To jsme p\u0159ece my.\u201c"],t.s)
B.bmq=new A.a6(B.bE,B.aqo,!1)
B.axx=new A.aQ("Bedna m\xe1 z\xe1mek. Ale kl\xed\u010d\u2026 nikde.")
B.aig=s([B.ayf,B.blz,B.bmq,B.axx],t.a)
B.boE=new A.cq("story_02",B.aig)
B.ax9=new A.aQ("Z\xe1mek cvakne a v\xedko odsko\u010d\xed. Uvnit\u0159 je hromada pap\xedr\u016f. Najednou se pap\xedry pohnou a vyb\u011bhne z nich mal\xe1 \u0161ed\xe1 my\u0161. Tobi vyp\xedskne. Ferda zak\u0148u\u010d\xed a schov\xe1 se Kl\xe1\u0159e za nohy.")
B.ajV=s(["\u201eFerdo, ty hrdino. Ty se boj\xed\u0161 my\u0161i?\u201c","\u201ePo\u010dkej. Na kalend\xe1\u0159i bylo zakrou\u017ekovan\xe9 jednadvac\xe1t\xe9 z\xe1\u0159\xed. To je p\u0159ece dneska! B jako Bohou\u0161. Tohle je d\u011bdova bedna!\u201c"],t.s)
B.bmj=new A.a6(B.bE,B.ajV,!1)
B.ayH=new A.aQ("My\u0161 si z pap\xedr\u016f ud\u011blala pel\xed\u0161ek. Tobi je opatrn\u011b p\u0159eb\xedr\xe1 a najde \xfatr\u017eek s nakreslen\xfdm praporkem.")
B.ak4=s(["\u201eKl\xe1ro\u2026 to je mapa k pokladu!\u201c"],t.s)
B.blL=new A.a6(B.bb,B.ak4,!1)
B.arP=s(["\u201eNebo n\xe1kupn\xed seznam.\u201c"],t.s)
B.bmB=new A.a6(B.bE,B.arP,!1)
B.abH=s(["\u201eNa n\xe1kupn\xed seznam se praporky nekresl\xed!\u201c"],t.s)
B.bl_=new A.a6(B.bb,B.abH,!1)
B.aiB=s(["\u201eA na mapu k pokladu se kresl\xed k\u0159\xed\u017eek. Vid\xed\u0161 tu n\u011bjak\xfd?\u201c"],t.s)
B.bkx=new A.a6(B.bE,B.aiB,!1)
B.ayL=new A.aQ("Na \xfatr\u017eku \u017e\xe1dn\xfd k\u0159\xed\u017eek nen\xed. Ale \xfatr\u017ek\u016f je v bedn\u011b spousta.")
B.aq2=s([B.ax9,B.bmj,B.ayH,B.blL,B.bmB,B.bl_,B.bkx,B.ayL],t.a)
B.boJ=new A.cq("story_03",B.aq2)
B.ard=s(["\u201eMapa kapit\xe1na Bohou\u0161e. Z roku 1964.\u201c"],t.s)
B.bla=new A.a6(B.bb,B.ard,!1)
B.ap7=s(["\u201e\u201aPevnost.\u2018 \u201aPozor! Dinosau\u0159i!\u2018 \u201aBa\u017eina smrti.\u2018\u201c","\u201eNo, to je teda zahrada.\u201c"],t.s)
B.bmF=new A.a6(B.bE,B.ap7,!1)
B.aqn=s(["\u201eDinosau\u0159i! D\u011bda m\u011bl na zahrad\u011b dinosaury?\u201c"],t.s)
B.bl1=new A.a6(B.bb,B.aqn,!1)
B.ad_=s(["\u201eJo, a j\xe1 m\xe1m pod postel\xed draka.\u201c"],t.s)
B.bmo=new A.a6(B.bE,B.ad_,!1)
B.aej=s(["\u201eJen tu mapu ta my\u0161 celou prokousala. Jsou v n\xed sam\xe9 d\xedry.\u201c"],t.s)
B.bmu=new A.a6(B.bb,B.aej,!1)
B.abT=s(["\u201ePevnost\u2026 Na zahrad\u011b ale \u017e\xe1dn\xe1 pevnost nen\xed. Je tam jen gar\xe1\u017e.\u201c"],t.s)
B.blX=new A.a6(B.bE,B.abT,!1)
B.aiy=s(["\u201ePevnost je p\u0159ece ka\u017ed\xe1 skr\xfd\u0161. Stan z deky. Sk\u0159\xed\u0148. Nebo\u2026 star\xe1 k\u016flna!\u201c"],t.s)
B.bmA=new A.a6(B.bb,B.aiy,!1)
B.akA=s(["\u201eTobi, ty jsi g\xe9nius! Babi\u010dka jednou \u0159\xedkala, \u017ee gar\xe1\u017e b\xfdvala k\u016flna.\u201c"],t.s)
B.bnK=new A.a6(B.bE,B.akA,!1)
B.ayr=new A.aQ("Tobi se za\u010derven\xe1. Takovou pochvalu od sestry je\u0161t\u011b nikdy nedostal.")
B.ax7=new A.aQ("D\u011bti se propl\xed\u017e\xed do gar\xe1\u017ee. Z\u016fstala v n\xed star\xe1 kamenn\xe1 ze\u010f a tlust\xfd tr\xe1m z doby, kdy tu st\xe1la k\u016flna.")
B.ae4=s(["\u201eKl\xe1ro, na tom tr\xe1mu n\u011bco je.\u201c"],t.s)
B.bl9=new A.a6(B.bb,B.ae4,!1)
B.alg=s(["\u201eVypad\xe1 to jako n\u011bjak\xe9 tajn\xe9 p\xedsmo. Kapit\xe1n Bohou\u0161 m\u011bl tajn\xe9 p\xedsmo?\u201c"],t.s)
B.bmf=new A.a6(B.bE,B.alg,!1)
B.aj3=s([B.bla,B.bmF,B.bl1,B.bmo,B.bmu,B.blX,B.bmA,B.bnK,B.ayr,B.ax7,B.bl9,B.bmf],t.a)
B.boA=new A.cq("story_04",B.aj3)
B.axj=new A.aQ("Ze\u010f se zachv\u011bje, k\xe1men zajede dovnit\u0159 a ze skr\xfd\u0161e se vysune plechov\xe1 krabi\u010dka. Uvnit\u0159 le\u017e\xed kompas.")
B.arh=s(["\u201eTo je skute\u010dn\xfd kapit\xe1nsk\xfd kompas!\u201c"],t.s)
B.bkt=new A.a6(B.bb,B.arh,!1)
B.ayN=new A.aQ("Pod kompasem je star\xe1 \u010dernob\xedl\xe1 fotka. Mal\xfd kluk s lopatkou u studny a \u010derven\xfd k\u0159\xed\u017eek. Na rubu je n\u011bco naps\xe1no.")
B.al1=s(["\u201e\u201aTady jsem ho zakopal. B.\u2018\u201c"],t.s)
B.bkV=new A.a6(B.bE,B.al1,!1)
B.ak8=s(["\u201eTen kluk\u2026 m\xe1 na hlav\u011b stejn\xfd chom\xe1\u010dek jako d\u011bda.\u201c"],t.s)
B.bn3=new A.a6(B.bb,B.ak8,!1)
B.aqi=s(["\u201eProto\u017ee to je d\u011bda, Tobi.\u201c"],t.s)
B.bng=new A.a6(B.bE,B.aqi,!1)
B.as9=s([B.axj,B.bkt,B.ayN,B.bkV,B.bn3,B.bng],t.a)
B.bp6=new A.cq("story_05",B.as9)
B.ayD=new A.aQ("Studna na zahrad\u011b stoj\xed dodnes. Kl\xe1ra se k n\xed rozb\u011bhne, ale Tobi ji chyt\xed za ruk\xe1v.")
B.adY=s(["\u201e\u010c\xe1ra vede p\u0159es v\u0161echny praporky. Kapit\xe1n by si to nezkracoval.\u201c"],t.s)
B.bmZ=new A.a6(B.bb,B.adY,!1)
B.aya=new A.aQ("Dal\u0161\xed praporek je u n\xe1pisu \u201ePozor! Dinosau\u0159i!\u201c. Dnes tam le\u017e\xed jen star\xe1 betonov\xe1 deska pod hromadou list\xed.")
B.anN=s(["\u201eCo kdy\u017e tu je\u0161t\u011b n\u011bjak\xfd je?\u201c"],t.s)
B.bmG=new A.a6(B.bb,B.anN,!1)
B.anV=s(["\u201e\u017d\xe1dn\xed dinosau\u0159i. Babi\u010dka \u0159\xedkala, \u017ee tady b\xfdval kurn\xedk.\u201c"],t.s)
B.bmL=new A.a6(B.bE,B.anV,!1)
B.adU=s(["\u201eSlepice? Tak to d\u011bda trochu p\u0159eh\xe1n\u011bl.\u201c"],t.s)
B.bmH=new A.a6(B.bb,B.adU,!1)
B.aqM=s(["\u201eVlastn\u011b ani ne. Slepice jsou potomci dinosaur\u016f.\u201c"],t.s)
B.bnk=new A.a6(B.bE,B.aqM,!1)
B.aft=s([B.ayD,B.bmZ,B.aya,B.bmG,B.bmL,B.bmH,B.bnk],t.a)
B.boY=new A.cq("story_06",B.aft)
B.adZ=s(["\u201eTak\u017ee kohout Rex nah\xe1n\u011bl mal\xe9ho d\u011bdu!\u201c"],t.s)
B.bkI=new A.a6(B.bE,B.adZ,!1)
B.aq9=s(["\u201eD\u011bda v\u017edycky vypr\xe1v\xed, jak lovil dinosaury. A p\u0159itom dinosaurus lovil jeho!\u201c"],t.s)
B.bmm=new A.a6(B.bb,B.aq9,!1)
B.axI=new A.aQ("Ferda nastra\u017e\xed u\u0161i. N\u011bco uc\xedt\xed a rozb\u011bhne se. D\u011bti se ho sna\u017e\xed chytit, ale on se \u017eene p\u0159es zahradu k m\xedstu, kter\xe9mu mapa \u0159\xedk\xe1 Ba\u017eina smrti. Ferda stoj\xed na star\xe9 fo\u0161n\u011b v bahn\u011b, vrt\xed ocasem a m\xed\u0159\xed ke kompostu.")
B.afM=s(["\u201eFerdo, k noze!\u201c"],t.s)
B.bkM=new A.a6(B.bE,B.afM,!1)
B.amV=s(["\u201eMus\xedme ho odtamtud n\u011bjak dostat.\u201c"],t.s)
B.blW=new A.a6(B.bb,B.amV,!1)
B.an1=s([B.bkI,B.bmm,B.axI,B.bkM,B.blW],t.a)
B.boO=new A.cq("story_07",B.an1)
B.ayq=new A.aQ("Ferda ch\u0148apne kost a sko\u010d\xed s n\xed rovnou do kompostu. Pak vylet\xed ven a cel\xfd u\u0161mudlan\xfd uh\xe1n\xed k domu.")
B.aqF=s(["\u201eNe, ne, ne, ne\u2026\u201c"],t.s)
B.bkY=new A.a6(B.bE,B.aqF,!1)
B.ayd=new A.aQ("Z domu se ozve \u0159in\u010den\xed a k\u0159ik. Za chvilku se Ferda p\u0159i\u0159\xedt\xed zp\xe1tky. Spokojen\xfd, umazan\xfd a se str\xfdcovou kravatou v zubech.")
B.abE=s(["\u201eAspo\u0148 u\u017e nebude vypr\xe1v\u011bt o hypot\xe9k\xe1ch. Te\u010f bude vypr\xe1v\u011bt o kravat\u011b.\u201c"],t.s)
B.bln=new A.a6(B.bb,B.abE,!1)
B.axu=new A.aQ("U studny Tobi zvedne fotku a porovn\xe1v\xe1. Studna je po\u0159\xe1d na stejn\xe9m m\xedst\u011b. Jen mal\xfd stromek, u kter\xe9ho stoj\xed mal\xfd Bohou\u0161, tu nikde nen\xed.")
B.ahF=s(["\u201e\u201aTady jsem ho zakopal.\u2018 Jen\u017ee kde je to \u201atady\u2018?\u201c"],t.s)
B.bkB=new A.a6(B.bb,B.ahF,!1)
B.aen=s([B.ayq,B.bkY,B.ayd,B.bln,B.axu,B.bkB],t.a)
B.bpb=new A.cq("story_08",B.aen)
B.axi=new A.aQ("Kol\xedk cinkne o n\u011bco tvrd\xe9ho. P\u0159\xedmo mezi ko\u0159eny obrovsk\xe9 jablon\u011b.")
B.ajz=s(["\u201eKl\xe1ro. Ten mal\xfd stromek\u2026 to je ta ob\u0159\xed jablo\u0148?\u201c"],t.s)
B.bks=new A.a6(B.bb,B.ajz,!1)
B.al7=s(["\u201e\u0160edes\xe1t let, Tobi. Mal\xe9 stromky za takovou dobu trochu vyrostou, v\xed\u0161?\u201c"],t.s)
B.blV=new A.a6(B.bE,B.al7,!1)
B.adR=s(["\u201eTak\u017ee d\u011bda byl taky jednou mal\xfd stromek.\u201c"],t.s)
B.bmT=new A.a6(B.bb,B.adR,!1)
B.ax0=new A.aQ("Kl\xe1ra p\u0159inese z gar\xe1\u017ee dv\u011b lopatky.")
B.ais=s(["\u201eJ\xe1 prvn\xed!\u201c"],t.s)
B.blY=new A.a6(B.bE,B.ais,!1)
B.apc=s(["\u201eNe, j\xe1!\u201c"],t.s)
B.bnh=new A.a6(B.bb,B.apc,!1)
B.axB=new A.aQ("Kopou oba najednou a Ferda kope s nimi. Pak lopatka naraz\xed na plechovou krabici. Ko\u0159eny jablon\u011b ji ale celou obrostly.")
B.aq6=s([B.axi,B.bks,B.blV,B.bmT,B.ax0,B.blY,B.bnh,B.axB],t.a)
B.bpd=new A.cq("story_09",B.aq6)
B.ayw=new A.aQ("Krabice je kone\u010dn\u011b voln\xe1. Je ale tak t\u011b\u017ek\xe1, \u017ee s n\xed d\u011bti ani nepohnou.")
B.fj=new A.kq("bohous","assets/images/stories/bohous/story/portrait_bohous.webp")
B.apq=s(["\u201eCopak to tu kopete, pr\u016fzkumn\xedci? Zlato? Nebo snad hled\xe1te krtky?\u201c"],t.s)
B.bm_=new A.a6(B.fj,B.apq,!1)
B.ayo=new A.aQ("Nad j\xe1mou stoj\xed d\u011bda. P\u0159i\u0161el se pod\xedvat, jakou neplechu zase prov\xe1d\xed Ferda. Pak si v\u0161imne krabice a zmlkne.")
B.aoR=s(["\u201eTo snad\u2026 to nen\xed mo\u017en\xe9.\u201c"],t.s)
B.blw=new A.a6(B.fj,B.aoR,!1)
B.axt=new A.aQ("D\u011bda si klekne do hl\xedny ve sv\xfdch sv\xe1te\u010dn\xedch kalhot\xe1ch a pohlad\xed rezav\xe9 v\xedko krabice.")
B.aiC=s([B.ayw,B.bm_,B.ayo,B.blw,B.axt],t.a)
B.bp5=new A.cq("story_10",B.aiC)
B.aoO=s(["\u201eBylo mi deset. T\xe1ta vykopal j\xe1mu a j\xe1 do krabice dal v\u0161echno, co jsem m\u011bl nejrad\u0161i. A pak jsem mu \u0159ekl: \u201aTati, otev\u0159eme ji spolu. Za deset let. Slib to!\u2018\u201c","\u201eA t\xe1ta sl\xedbil. Napsali jsme to na pap\xedr a oba se podepsali. Jen\u017ee za deset let jsem byl na vojn\u011b, pak p\u0159i\u0161la svatba, d\u011bti\u2026 a na kapsli jsme \xfapln\u011b zapomn\u011bli.\u201c"],t.s)
B.bmg=new A.a6(B.fj,B.aoO,!1)
B.aoW=s(["\u201eTak ji otev\u0159i te\u010f, d\u011bdo. S n\xe1mi.\u201c"],t.s)
B.bnF=new A.a6(B.bb,B.aoW,!1)
B.axf=new A.aQ("Na v\xedku nejsou \u017e\xe1dn\xe9 z\xe1mky, jen vyryt\xe1 p\xedsmenka. Kl\xe1ra polo\u017e\xed vedle kapsle kompas. Tobi rozlo\u017e\xed mapu.")
B.adA=s(["\u201eJen \u0161koda t\u011bch d\u011br od my\u0161i.\u201c"],t.s)
B.bnC=new A.a6(B.bb,B.adA,!1)
B.art=s(["\u201eMy\u0161? Kdepak! Ty d\xedry vy\u0159\xedzl t\xe1ta. Ta mapa je kl\xed\u010d ke kapsli.\u201c","\u201eJen\u017ee jak se s n\xed otev\xedr\xe1\u2026 to si u\u017e nepamatuju.\u201c"],t.s)
B.bkn=new A.a6(B.fj,B.art,!1)
B.akD=s([B.bmg,B.bnF,B.axf,B.bnC,B.bkn],t.a)
B.boU=new A.cq("story_11",B.akD)
B.axA=new A.aQ("Pod dvojit\xfdm dnem le\u017e\xed kapesn\xed hodinky.")
B.anZ=s(["\u201eDvojit\xe9 dno? O tom jsem v\u016fbec nev\u011bd\u011bl! To mi t\xe1ta ne\u0159ekl.\u201c"],t.s)
B.blD=new A.a6(B.fj,B.anZ,!1)
B.axX=new A.aQ("D\u011bda vezme hodinky do dlan\u011b a dlouze se na n\u011b d\xedv\xe1.")
B.alz=s(["\u201eT\xe1tovy hodinky. Myslel jsem, \u017ee se d\xe1vno ztratily.\u201c"],t.s)
B.blx=new A.a6(B.fj,B.alz,!1)
B.ayv=new A.aQ("Pod hodinkami le\u017e\xed slo\u017een\xfd l\xedste\u010dek.")
B.arZ=s(["\u201e\u201aMil\xfd Bohou\u0161i, dnes je Ti dvacet let. Tyhle hodinky jsem dostal od sv\xe9ho t\xe1ty, kdy\u017e mi bylo dvacet. Te\u010f jsou Tvoje. Jsem na Tebe py\u0161n\xfd. T\xe1ta.\u2018\u201c"],t.s)
B.bmx=new A.a6(B.fj,B.arZ,!1)
B.ax3=new A.aQ("Chv\xedli je ticho. D\u011bda nat\xe1hne hodinky a po \u0161edes\xe1ti letech se znovu ozve: tik, tak, tik, tak.")
B.agL=s(["\u201eD\u011bdo, ty pl\xe1\u010de\u0161?\u201c"],t.s)
B.bno=new A.a6(B.bb,B.agL,!1)
B.aki=s(["\u201ePl\xe1\u010du. Ale radost\xed.\u201c"],t.s)
B.bnT=new A.a6(B.fj,B.aki,!1)
B.ay6=new A.aQ("Kl\xe1ra a Tobi d\u011bdu obejmou. Ferda se p\u0159id\xe1 taky, i kdy\u017e je po\u0159\xe1d cel\xfd od bl\xe1ta.")
B.ahD=s([B.axA,B.blD,B.axX,B.blx,B.ayv,B.bmx,B.ax3,B.bno,B.bnT,B.ay6],t.a)
B.boV=new A.cq("story_12",B.ahD)
B.ay8=new A.aQ("Ve\u010der sed\xed cel\xe1 rodina pod jablon\xed. Na stole le\u017e\xed v\u0161echno z kapsle a Kl\xe1ra \u010dte Bohou\u0161ovy p\u0159edpov\u011bdi.")
B.alB=s(["\u201e\u201aV roce 1974. Jedna: budu kapit\xe1n. Dva: auta budou l\xe9tat. T\u0159i: Rex snese vejce.\u2018\u201c","\u201eD\u011bdo. Kohouti vejce nesn\xe1\u0161ej\xed.\u201c"],t.s)
B.bns=new A.a6(B.bE,B.alB,!1)
B.aos=s(["\u201eRex byl v\xfdjime\u010dn\xfd kohout. V\u011b\u0159il jsem mu!\u201c"],t.s)
B.blE=new A.a6(B.fj,B.aos,!1)
B.ayP=new A.aQ("V\u0161ichni se za\u010dnou sm\xe1t.")
B.aeb=s(["\u201eTohle je nejlep\u0161\xed oslava na sv\u011bt\u011b.\u201c"],t.s)
B.bkq=new A.a6(B.bb,B.aeb,!1)
B.ar4=s([B.ay8,B.bns,B.blE,B.ayP,B.bkq],t.a)
