B.aU4=new A.iS("Kl\xed\u010de z denn\xedch h\xe1danek otev\xedraj\xed zlat\xe9 z\xe1mky. Kdy\u017e otev\u0159e\u0161 v\u0161echny, z\xedsk\xe1\u0161 novou poh\xe1dku do sv\xe9 knihovni\u010dky.","Kl\xed\u010de odemykaj\xed poh\xe1dky")
B.alp=s([B.aU4],t.Lp)
B.bBv=new A.bq(1,"cvakne","sfx_story_bolt",null,1)
B.bBe=new A.bq(1,"otev\u0159ou","sfx_story_doors_morning",null,1)
B.bB7=new A.bq(9,"odjede","sfx_story_truck_leave",null,1)
B.bBz=new A.bq(9,"tik\xe1n\xed","sfx_story_soft_ticking",null,1)
B.alr=s([B.bBv,B.bBe,B.bB7,B.bBz],t.c)
B.b5d=new A.e(0,0,170.20355132091814,311.82330012992634)
B.b5Y=new A.e(120,0,311.85794716327416,170.20355132091814)
B.b2G=new A.e(129.9,129.9,311.79692507579034,311.79692507579034)
B.l8=s([B.b5d,B.b5Y,B.b2G],t.u)
B.axZ=new A.aQ("Za jednou vesnic\xed roste velk\xfd les, kter\xfd nezn\xe1 \u017e\xe1dn\xfd nudn\xfd dosp\u011bl\xe1k. V n\u011bm stoj\xed star\xe1 vrba s tajnou klubovnou uvnit\u0159 kmene. Dnes se k n\xed poprv\xe9 bl\xed\u017e\xed\u0161 i ty. A to zrovna v den, kdy maj\xed str\xe1\u017eci stolet\xe9 narozeniny.")
B.cH=new A.kq("marek","assets/images/stories/forest_rangers/portrait_marek.webp")
B.aeo=s(["\u201eSt\u016fj! Dovnit\u0159 sm\xed jen ten, kdo zn\xe1 tajn\xfd pozdrav.\u201c"],t.s)
B.bkZ=new A.a6(B.cH,B.aeo,!1)
B.bV=new A.kq("karel","assets/images/stories/forest_rangers/portrait_karel.webp")
B.aiY=s(["\u201eChce\u0161 se k n\xe1m p\u0159idat? M\xe1\u0161 dobr\xfd post\u0159eh?\u201c"],t.s)
B.bnA=new A.a6(B.bV,B.aiY,!1)
B.aoI=s([B.axZ,B.bkZ,B.bnA],t.a)
B.bp9=new A.cq("story_00_intro",B.aoI)
B.axh=new A.aQ("Dve\u0159e se otev\u0159ou do tmy a ty vstoup\xed\u0161 dovnit\u0159. Klubovna von\xed d\u0159evem a star\xfdm pap\xedrem. Uprost\u0159ed stoj\xed st\u016fl a na n\u011bm le\u017e\xed podivn\xfd den\xedk.")
B.afb=s(["\u201eDve\u0159e se otev\u0159ely, tak\u017ee pozdrav u\u017e zn\xe1\u0161. J\xe1 se jmenuji Marek, tamto byl Karel a tohle je Tereza. Poj\u010f d\xe1l.\u201c"],t.s)
B.bl8=new A.a6(B.cH,B.afb,!1)
B.ay5=new A.aQ("Za dve\u0159mi se ozve hlasit\xe9 \u017euchnut\xed.")
B.afl=s(["\u201eJsem v po\u0159\xe1dku! Spadl jsem schv\xe1ln\u011b, abych prolomil ledy.\u201c"],t.s)
B.bl4=new A.a6(B.bV,B.afl,!1)
B.cS=new A.kq("tereza","assets/images/stories/forest_rangers/portrait_tereza.webp")
B.apX=s(["\u201eMarku! N\xe1\u0161 den\xedk nejde otev\u0159\xedt.\u201c","\u201eV\u010dera ve\u010der ho omotala divok\xe1 li\xe1na.\u201c","\u201eZkou\u0161eli jsme ji odmotat, ale li\xe1na dr\u017e\xed jako p\u0159ilepen\xe1.\u201c"],t.s)
B.bnl=new A.a6(B.cS,B.apX,!1)
B.afH=s(["\u201eBez den\xedku nem\u016f\u017eeme d\u011blat pr\u016fzkum lesa.\u201c"],t.s)
B.bmD=new A.a6(B.cH,B.afH,!1)
B.aoV=s([B.axh,B.bl8,B.ay5,B.bl4,B.bnl,B.bmD],t.a)
B.boK=new A.cq("story_01a_clubhouse_arrival",B.aoV)
B.ahc=s(["\u201eA dneska to pot\u0159ebujeme v\xedc ne\u017e kdy jindy! Klub m\xe1 st\xe9 narozeniny.\u201c"],t.s)
B.blN=new A.a6(B.cH,B.ahc,!1)
B.ajl=s(["\u201ePodle legendy se pr\xe1v\u011b dnes d\xe1 naj\xedt to, co po sob\u011b zakladatel\xe9 nechali. Jen\u017ee jen do z\xe1padu slunce.\u201c"],t.s)
B.bmK=new A.a6(B.cS,B.ajl,!1)
B.ad1=s(["\u201ePoklad! T\u0159eba jedl\xfd poklad. Dort! Ur\u010dit\u011b to bude dort.\u201c"],t.s)
B.bn5=new A.a6(B.bV,B.ad1,!1)
B.afg=s(["\u201eNikdo ne\u0159ekl poklad.\u201c"],t.s)
B.bn1=new A.a6(B.cS,B.afg,!1)
B.aer=s(["\u201eNikdo ne\u0159ekl, \u017ee nen\xed.\u201c"],t.s)
B.bm4=new A.a6(B.bV,B.aer,!1)
B.abL=s(["\u201eCokoliv to je, najdeme to. Dal\u0161\xed \u0161ance p\u0159ijde a\u017e za sto let.\u201c"],t.s)
B.bkJ=new A.a6(B.cH,B.abL,!1)
B.amg=s(["\u201eTo bych ten dort nestihl ochutnat.\u201c"],t.s)
B.bnG=new A.a6(B.bV,B.amg,!1)
B.arJ=s([B.blN,B.bmK,B.bn5,B.bn1,B.bm4,B.bkJ,B.bnG],t.a)
B.boD=new A.cq("story_01b_legend_and_time",B.arJ)
B.ayJ=new A.aQ("Li\xe1na povol\xed, den\xedk se otev\u0159e a vypadne z n\u011bj hrom\xe1dka pap\xedrov\xfdch \xfatr\u017ek\u016f.")
B.ahl=s(["\u201eTo je star\xe1 mapa lesa!\u201c"],t.s)
B.blU=new A.a6(B.bV,B.ahl,!1)
B.agp=s(["\u201eAle ne, n\u011bkdo ji roztrhal. Karle?\u201c"],t.s)
B.bnR=new A.a6(B.cS,B.agp,!1)
B.aqW=s(["\u201eJ\xe1 to nebyl. \u2026 Asi.\u201c"],t.s)
B.bn0=new A.a6(B.bV,B.aqW,!1)
B.alG=s(["\u201ePap\xedr je star\u0161\xed ne\u017e na\u0161e babi\u010dky. Tenhle se roztrhne i s\xe1m.\u201c"],t.s)
B.bkD=new A.a6(B.cS,B.alG,!1)
B.ae6=s(["\u201eDob\u0159e. Co te\u010f s t\xedm?\u201c"],t.s)
B.bkG=new A.a6(B.cH,B.ae6,!1)
B.ajY=s([B.ayJ,B.blU,B.bnR,B.bn0,B.bkD,B.bkG],t.a)
B.boC=new A.cq("story_02_torn_map",B.ajY)
B.ad2=s(["\u201eKoukejte! To je cesta zakladatel\u016f klubu.\u201c"],t.s)
B.blT=new A.a6(B.cH,B.ad2,!1)
B.amO=s(["\u201eCo kdybychom se za\u0161li pod\xedvat, odkud k n\xe1m zakladatel\xe9 p\u0159i\u0161li?\u201c"],t.s)
B.bnr=new A.a6(B.bV,B.amO,!1)
B.axL=new A.aQ("\u010cerven\xe1 \u010d\xe1ra na map\u011b vede hluboko do lesa. Stoj\xedte p\u0159ed cestou z kamen\u016f, kterou blokuje trn\xed.")
B.aq1=s(["\u201eCesta z mapy vede p\u0159\xedmo tudy.\u201c"],t.s)
B.bnt=new A.a6(B.cS,B.aq1,!1)
B.aqm=s(["\u201eJ\xe1 p\u0159es ty kameny a trn\xed nejdu, Terko.\u201c"],t.s)
B.bny=new A.a6(B.bV,B.aqm,!1)
B.al_=s(["\u201eNikdo ne\u0159ekl, \u017ee to bude snadn\xe9, K\xe1jo. Tak poj\u010f.\u201c","\u201eZa mnou! Str\xe1\u017eci se n\u011bjak\xe9ho trn\xed neboj\xed.\u201c"],t.s)
B.bl6=new A.a6(B.cH,B.al_,!1)
B.adu=s(["\u201eStr\xe1\u017eci se neboj\xed, ale bod\xe1 to \xfapln\u011b stejn\u011b jako do kohokoli jin\xe9ho.\u201c"],t.s)
B.blK=new A.a6(B.bV,B.adu,!1)
B.adC=s([B.blT,B.bnr,B.axL,B.bnt,B.bny,B.bl6,B.blK],t.a)
B.boF=new A.cq("story_03_founders_trail",B.adC)
B.axl=new A.aQ("Trn\xed se rozestoup\xed a dovol\xed v\xe1m proj\xedt d\xe1l. Na m\xfdtin\u011b s m\u011bkk\xfdm bahnem jsou jemn\xe9 otisky kv\u011btin.")
B.afZ=s(["\u201eKdo by v\xe1lel kv\u011btiny v bahn\u011b?\u201c"],t.s)
B.bnL=new A.a6(B.bV,B.afZ,!1)
B.am8=s(["\u201eZakladatel\xe9 klubu takto zna\u010dili cestu.\u201c","\u201eAle ne! Vypad\xe1 to, \u017ee je n\u011bkdo odnesl.\u201c"],t.s)
B.bmV=new A.a6(B.cS,B.am8,!1)
B.apG=s(["\u201eA co s t\xedm te\u010f budeme d\u011blat? J\xe1 u\u017e m\xe1m bahno po kotn\xedky!\u201c"],t.s)
B.bn6=new A.a6(B.bV,B.apG,!1)
B.ahH=s(["\u201ePod\xedv\xe1me se kolem, jestli n\u011bjak\xe9 nenajdeme.\u201c"],t.s)
B.bmM=new A.a6(B.cH,B.ahH,!1)
B.acw=s([B.axl,B.bnL,B.bmV,B.bn6,B.bmM],t.a)
B.boz=new A.cq("story_04_flowers_in_mud",B.acw)
B.axQ=new A.aQ("Posledn\xed kv\u011btina zapadne na sv\xe9 m\xedsto a cel\xe1 m\xfdtina rozkvete. Mezi kv\u011bty se objev\xed \xfazk\xe1 p\u011b\u0161inka, kter\xe1 kon\u010d\xed u mohutn\xe9ho dubu.")
B.aeT=s(["\u201eTen dub je ur\u010dit\u011b star\u0161\xed ne\u017e my v\u0161ichni dohromady.\u201c"],t.s)
B.blh=new A.a6(B.bV,B.aeT,!1)
B.abR=s(["\u201ePodle kmene m\xe1 aspo\u0148 p\u011bt set let.\u201c","\u201eHele veverka a vypad\xe1, \u017ee n\u011bco hl\xedd\xe1.\u201c"],t.s)
B.bmC=new A.a6(B.cS,B.abR,!1)
B.aij=s(["\u201eKouk\xe1 na m\u011b n\u011bjak hladov\u011b.\u201c"],t.s)
B.bnW=new A.a6(B.bV,B.aij,!1)
B.arV=s(["\u201ePoj\u010fme se pod\xedvat bl\xed\u017e.\u201c"],t.s)
B.blJ=new A.a6(B.cH,B.arV,!1)
B.alx=s([B.axQ,B.blh,B.bmC,B.bnW,B.blJ],t.a)
B.bpl=new A.cq("story_05_old_oak",B.alx)
B.axM=new A.aQ("\u017daludy zmiz\xed v dutin\u011b dubu. Star\xfd dub se rozz\xe1\u0159\xed tepl\xfdm sv\u011btlem a zlat\xe1 z\xe1\u0159e miz\xed v d\xe1lce.")
B.amT=s(["\u201eCo se to stalo?\u201c"],t.s)
B.bnz=new A.a6(B.bV,B.amT,!1)
B.ai6=s(["\u201eVypad\xe1 to, jako bychom n\u011bco probudili.\u201c"],t.s)
B.blH=new A.a6(B.cH,B.ai6,!1)
B.af1=s(["\u201ePros\xedm, a\u0165 je to n\u011bco roztomil\xe9ho.\u201c"],t.s)
B.blF=new A.a6(B.bV,B.af1,!1)
B.aj0=s(["\u201eZa sv\u011btlem! Dub n\xe1m ukazuje cestu.\u201c"],t.s)
B.bmP=new A.a6(B.cH,B.aj0,!1)
B.axs=new A.aQ("Jdete sm\u011brem k z\xe1\u0159i. Zlat\xe9 sv\u011btlo v\xe1s dovede a\u017e k vodop\xe1du, kde ve skaln\xedm v\xfdklenku le\u017e\xed star\xe1 truhla.")
B.ain=s(["\u201eTakovou truhlu jsem je\u0161t\u011b nevid\u011bla.\u201c"],t.s)
B.bmw=new A.a6(B.cS,B.ain,!1)
B.arz=s([B.axM,B.bnz,B.blH,B.blF,B.bmP,B.axs,B.bmw],t.a)
B.boG=new A.cq("story_06_waterfall_chest",B.arz)
B.ay4=new A.aQ("V\xedko se zvedne. Uvnit\u0159 le\u017e\xed svitek p\u0159ev\xe1zan\xfd prov\xe1zkem.")
B.agu=s(["\u201eSlunce u\u017e se dot\xfdk\xe1 korun strom\u016f!\u201c"],t.s)
B.bnY=new A.a6(B.cS,B.agu,!1)
B.ars=s(["\u201eHonem zp\u011bt do klubovny!\u201c","\u201eNev\xedme, co ten svitek skr\xfdv\xe1. Mus\xedme b\xfdt opatrn\xed.\u201c"],t.s)
B.blI=new A.a6(B.cH,B.ars,!1)
B.ayy=new A.aQ("Po n\xe1vratu do klubovny otev\u0159e\u0161 svitek. Sotva ho rozvine\u0161, vyl\xe9tnou z n\u011bj velk\xe9 bubliny.")
B.arH=s([B.ay4,B.bnY,B.blI,B.ayy],t.a)
B.bp1=new A.cq("story_07_scroll",B.arH)
B.ax6=new A.aQ("Posledn\xed paprsek slunce dopadne na svitek a klubovna se rozsv\xedt\xed lucernami.")
B.apw=s(["\u201eTo je v\u0161echno? J\xe1 \u010dekal poklad.\u201c"],t.s)
B.bnM=new A.a6(B.bV,B.apw,!1)
B.anD=s(["\u201eCel\xe1 ta cesta byla zkou\u0161ka, K\xe1jo. Cht\u011bli zjistit, jestli m\xe1me trp\u011blivost.\u201c"],t.s)
B.bkr=new A.a6(B.cS,B.anD,!1)
B.afd=s(["\u201eA pro\u010d to nenapsali rovnou na dve\u0159e?\u201c"],t.s)
B.bkz=new A.a6(B.bV,B.afd,!1)
B.ajG=s(["\u201eProto\u017ee by t\u011b nebavilo to hledat.\u201c"],t.s)
B.bli=new A.a6(B.cS,B.ajG,!1)
B.akI=s(["\u201eTrp\u011blivost \u2026 ta mi nikdy moc ne\u0161la.\u201c"],t.s)
B.bnv=new A.a6(B.cH,B.akI,!1)
B.aly=s(["\u201eMarku, ty jsi v \u017eivot\u011b nepo\u010dkal ani na konec v\u011bty.\u201c"],t.s)
B.bkm=new A.a6(B.cS,B.aly,!1)
B.alt=s(["\u201eJ\xe1 \u010dek\xe1m na dort a trp\u011blivost m\xe1m.\u201c"],t.s)
B.blk=new A.a6(B.bV,B.alt,!1)
B.ail=s(["\u201eTo nen\xed trp\u011blivost, K\xe1jo. To je hlad.\u201c"],t.s)
B.bme=new A.a6(B.cS,B.ail,!1)
B.aem=s(["\u201eA tob\u011b se zkou\u0161ka povedla. Bez tebe bychom to do z\xe1padu nestihli.\u201c"],t.s)
B.bl3=new A.a6(B.cH,B.aem,!1)
B.adS=s([B.ax6,B.bnM,B.bkr,B.bkz,B.bli,B.bnv,B.bkm,B.blk,B.bme,B.bl3],t.a)
B.boN=new A.cq("story_08_ending_dialogue",B.adS)
B.alH=s([B.bp9,B.boK,B.boD,B.boC,B.boF,B.boz,B.bpl,B.boG,B.bp1,B.boN],t.WD)
